CREATE TABLE "c_Account" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Account_account_no" TEXT, "a_Account_balance" NUMERIC, "a_CheckingAccount_overdraft_limit" NUMERIC, "a_SavingsAccount_interest_rate" DOUBLE PRECISION, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Account','CheckingAccount','SavingsAccount')), CHECK ((dtype IN ('Account','CheckingAccount','SavingsAccount')) OR "a_Account_account_no" IS NULL), CHECK (NOT (dtype IN ('Account','CheckingAccount','SavingsAccount')) OR "a_Account_account_no" IS NOT NULL), CHECK ((dtype IN ('Account','CheckingAccount','SavingsAccount')) OR "a_Account_balance" IS NULL), CHECK (NOT (dtype IN ('Account','CheckingAccount','SavingsAccount')) OR "a_Account_balance" IS NOT NULL), CHECK ((dtype IN ('CheckingAccount')) OR "a_CheckingAccount_overdraft_limit" IS NULL), CHECK (NOT (dtype IN ('CheckingAccount')) OR "a_CheckingAccount_overdraft_limit" IS NOT NULL), CHECK ((dtype IN ('SavingsAccount')) OR "a_SavingsAccount_interest_rate" IS NULL), CHECK (NOT (dtype IN ('SavingsAccount')) OR "a_SavingsAccount_interest_rate" IS NOT NULL));
CREATE TABLE "c_Party" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Business_tax_id_hash" TEXT, "a_Party_name" TEXT, "a_Person_ssn_hash" TEXT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Business','Party','Person')), CHECK ((dtype IN ('Business')) OR "a_Business_tax_id_hash" IS NULL), CHECK (NOT (dtype IN ('Business')) OR "a_Business_tax_id_hash" IS NOT NULL), CHECK ((dtype IN ('Business','Party','Person')) OR "a_Party_name" IS NULL), CHECK (NOT (dtype IN ('Business','Party','Person')) OR "a_Party_name" IS NOT NULL), CHECK ((dtype IN ('Person')) OR "a_Person_ssn_hash" IS NULL), CHECK (NOT (dtype IN ('Person')) OR "a_Person_ssn_hash" IS NOT NULL));
CREATE TABLE "c_Transaction" ("id" BIGINT NOT NULL, "a_Transaction_amount" NUMERIC NOT NULL, "a_Transaction_posted_at" TIMESTAMP NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_AccountTransactions" ("r_AccountTransactions_source_id" BIGINT NOT NULL, "r_AccountTransactions_source_dtype" TEXT NOT NULL, "r_AccountTransactions_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_AccountTransactions_source_id", "r_AccountTransactions_target_id"), UNIQUE ("r_AccountTransactions_target_id"), CHECK ("r_AccountTransactions_source_dtype" IS NULL OR "r_AccountTransactions_source_dtype" IN ('Account','CheckingAccount','SavingsAccount')));
CREATE TABLE "l_PartyAccounts" ("r_PartyAccounts_source_id" BIGINT NOT NULL, "r_PartyAccounts_source_dtype" TEXT NOT NULL, "r_PartyAccounts_target_id" BIGINT NOT NULL, "r_PartyAccounts_target_dtype" TEXT NOT NULL, PRIMARY KEY ("r_PartyAccounts_source_id", "r_PartyAccounts_target_id"), CHECK ("r_PartyAccounts_source_dtype" IS NULL OR "r_PartyAccounts_source_dtype" IN ('Business','Party','Person')), CHECK ("r_PartyAccounts_target_dtype" IS NULL OR "r_PartyAccounts_target_dtype" IN ('Account','CheckingAccount','SavingsAccount')));
ALTER TABLE "l_AccountTransactions" ADD CONSTRAINT "fk_l_AccountTransactions_0" FOREIGN KEY ("r_AccountTransactions_source_id", "r_AccountTransactions_source_dtype") REFERENCES "c_Account" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_AccountTransactions" ADD CONSTRAINT "fk_l_AccountTransactions_1" FOREIGN KEY ("r_AccountTransactions_target_id") REFERENCES "c_Transaction" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PartyAccounts" ADD CONSTRAINT "fk_l_PartyAccounts_0" FOREIGN KEY ("r_PartyAccounts_source_id", "r_PartyAccounts_source_dtype") REFERENCES "c_Party" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PartyAccounts" ADD CONSTRAINT "fk_l_PartyAccounts_1" FOREIGN KEY ("r_PartyAccounts_target_id", "r_PartyAccounts_target_dtype") REFERENCES "c_Account" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_AccountTransactions"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Transaction" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_AccountTransactions" l WHERE l."r_AccountTransactions_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: AccountTransactions'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_AccountTransactions_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Transaction" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_AccountTransactions"();
CREATE CONSTRAINT TRIGGER "ct_AccountTransactions_link" AFTER INSERT OR UPDATE OR DELETE ON "l_AccountTransactions" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_AccountTransactions"();